136	  wonDealTitle?: string | null;
137	  wonDealValue?: number | null;
138	  boughtByDeal: boolean;
139	}): CatalogScoreResult {
140	  const purchaseReason = input.boughtByDeal
141	    ? 'won_deal_recorded'
142	    : 'payment_or_access_confirmed_in_chat';
143	  const purchasedProduct =
144	    String(input.wonDealTitle || '').trim() ||
145	    (CURSO_PLANO_MENTORIA_PR_RE.exec(input.text)?.[0] ?? null);
146	  const purchaseValueRaw = Number(input.wonDealValue || 0) || 0;
147	  const positivePostPurchaseSignal = OBRIGAD_VALEU_PERFEITO_RE.test(input.text);
148	  const repurchaseProbabilityScore = positivePostPurchaseSignal ? 0.78 : 0.56;
